ACCESS_RULE = '    ("/csvc", frozenset({*ADMIN_ROLE_CODES, DEPARTMENT_ROLE_CODE, COMMUNE_ROLE_CODE, SCHOOL_ROLE_CODE})),\n'
OLD_FIN_REPORT = '        "description": "Mẫu tài chính chính thức. CSDL hiện chưa có phân hệ tài chính nên không tự suy diễn số liệu.",\n        "icon": "💰",\n        "stage": "Sẵn sàng mẫu – chờ dữ liệu tài chính",\n        "stage_class": "next",\n        "lesson": "PCGD & XMC V1.6B",'
